insert into civdrf_filtri
       (ID, ID_CIVDRF, SIGLA_CATEGORIA,
        TIPO_FILIAZIONE, TIPO_DICHIARANTE, TIPO_COMPARENTE, TIPO_FIRMATARIO, 
        COMPRENSIONE_DIC, NATO_MORTO,
        PARTO_PLURIMO, PARTO_PLURIMO_FLAG_PRIMO, PARTO_PLURIMO_FLAG_ULTIMO, PARTO_PLURIMO_FLAG_BIGEMINO,
        TIPO_ADDETTO_DICHIARAZIONE_CNA, ATTO_NOTARILE, FLAG_DEFAULT, 
        VERSION, TIPO_RICONOSCIMENTO, TIPO_CONSENSO)
select to_number(null),
       drf.id,
       'O1A',
       '',
       '',
       '',
       '',
       '',
       '',
       '',
       'N',
       'N',
       'N',
       '',
       'N',
       'S',
       0,
       '',
       ''
  from civdrf drf
 where drf.tipo_atto       = 2
   and drf.richiamo        = 1
   and drf.progr_dettaglio = 0
   and drf.formula         = '2-TES'
   and not exists (select 1 from civdrf_filtri b
                    where b.id_civdrf                                 = drf.id
                      and b.SIGLA_CATEGORIA                           = 'O1A'
                      and nvl(b.TIPO_FILIAZIONE,' ')                  = nvl('',' ')
                      and nvl(b.TIPO_DICHIARANTE,' ')                 = nvl('',' ')
                      and nvl(b.TIPO_COMPARENTE,' ')                  = nvl('',' ')
                      and nvl(b.TIPO_FIRMATARIO,' ')                  = nvl('',' ')
                      and nvl(b.COMPRENSIONE_DIC,' ')                 = nvl('',' ')
                      and nvl(b.NATO_MORTO,' ')                       = nvl('',' ')
                      and nvl(b.PARTO_PLURIMO,' ')                    = nvl('',' ')
                      and nvl(b.PARTO_PLURIMO_FLAG_PRIMO,' ')         = nvl('N',' ')
                      and nvl(b.PARTO_PLURIMO_FLAG_ULTIMO,' ')        = nvl('N',' ')
                      and nvl(b.PARTO_PLURIMO_FLAG_BIGEMINO,' ')      = nvl('N',' ')
                      and nvl(b.TIPO_ADDETTO_DICHIARAZIONE_CNA,' ')   = nvl('',' ')
                      and nvl(b.ATTO_NOTARILE,' ')                    = nvl('N',' ')
                      and nvl(b.TIPO_RICONOSCIMENTO,' ')              = nvl('',' ')
                      and nvl(b.TIPO_CONSENSO,' ')                    = nvl('',' ')
                  )
/
